import Header from "./header/header";
import Body from "./body/body";
import Footer from "./footer/footer";
// import Background from "./background/background";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
} from "react-router-dom";

import GamesPage from "./pages/games/games_page";
import ProjectsPage from "./pages/projects/projects_page";
import SocialPage from "./pages/social/social_page";
import AboutPage from "./pages/about/about_page";
import Player from "./pages/player/player";
import NotFound from "./pages/not_found.js";

const App = () => {
  return ( 
    <div className="d-flex flex-column justify-content-between w-100 min-vh-100 background moving-bg">
      <Router>
        <Header />
        <Routes>
          <Route index element={<Navigate replace to="games" />} />
          <Route path="/" element={<Body />}>
            <Route path="player/:game" element={<Player />} />
            <Route path="games" element={<GamesPage />}>
              <Route path=":game" element={<GamesPage />} />
            </Route>
            <Route path="about" element={<AboutPage />} />
            <Route path="social" element={<SocialPage />} />
            <Route path="projects" element={<ProjectsPage />} />
            <Route path="*" element={<NotFound />} />
          </Route>
        </Routes>
        <Footer />
      </Router>
    </div>
  );
};
