import projectsData from "./projects_data.json";
import PageHeader from "../page_header";
import { useState, useEffect } from "react";
const ProjectsPage = () => {
  const [projects, setProjects] = useState(projectsData);
  useEffect(() => {
    if (projects.length === 0) {
      console.log("WOOo");
      fetch(
        "https://api.github.com/repos/saantonandre/saantonandre.github.io/contents/projects"
      )
        .then((response) => response.json())
        .then((data) => {
          if (Array.isArray(data)) {
            setProjects(data);
          } else {
            setProjects(projectsData);
          }
        })
        .catch(() => {
          setProjects(projectsData);
        });
    }
  }, []);
  return (
    <>
      <PageHeader section="projects" />
      <div className="d-block">
        <div className="d-flex flex-row flex-wrap gap-3 p-3">
          {projects === [] && <i className="spinner-border" role="status" />}
          {projects.map((project) => {
            return (
              <a
                rel="noreferrer"
                target="_blank"
                href={"https://saantonandre.github.io/projects/" + project.name}
                style={{ height: "10rem", width: "10rem" }}
                key={`${project.name}-card`}
                role="button"
                className="d-flex justify-content-center align-items-center card bg-fadeblack flex-grow-1"
                
              >
                <div className="bg-black w-100 fs-5 text-center">{project.name}</div>
              </a>
            );
          })}
        </div>
      </div>
    </>
  );
};
export default ProjectsPage;
